// ngrok agent v3.39.13 (latest per ngrok apt repo / Homebrew cask / agent changelog, 2026-11-19). Source: ngrok/ngrok-docs data/generated/cli.json (agent command tree generated by ngrok, docs HEAD 2026-11-19) plus gateway/agent/cli.mdx, service.mdx and upgrade-v2-v3.mdx.
// Limits: the ngrok binary itself was not run here (download blocked), so flag value types are not machine-verified. Types of the plain `ngrok http|tcp|tls|start|config` flags come from cobra help text in the docs and common usage; the 300+ `ngrok api ...` commands are generated from cli.json with only `*.enabled`-style flags treated as booleans. The --log* flags are treated as global (shown on `config upgrade` and `api` commands in the docs).
// Single-dash long flags (-config, -log, -region, ...) were removed: agent v3 only accepts `--` long flags.

type ApiLeaf = [
  name: string,
  description: string,
  args: string,
  flags: string,
  overrides?: Record<string, string>
];
type ApiGroup = [name: string, description: string, children: ApiNode[]];
type ApiNode = ApiLeaf | ApiGroup;

const regions = ["us", "us-cal-1", "eu", "au", "ap", "sa", "jp", "in"];

const valueOption = (
  name: string,
  description: string,
  arg: string | Fig.Arg = name,
  extra: Partial<Fig.Option> = {}
): Fig.Option => ({
  name: `--${name}`,
  description,
  args: typeof arg === "string" ? { name: arg } : arg,
  ...extra,
});

const booleanOption = (
  name: string,
  description: string,
  extra: Partial<Fig.Option> = {}
): Fig.Option => ({
  name: `--${name}`,
  description,
  ...extra,
});

const deprecatedOption = (
  name: string,
  description: string,
  replacement: string,
  arg?: string | Fig.Arg
): Fig.Option => {
  const text = description
    ? `${description} (deprecated, ${replacement})`
    : `Deprecated, ${replacement}`;
  return arg === undefined
    ? booleanOption(name, text, { deprecated: true })
    : valueOption(name, text, arg, { deprecated: true });
};

