const cidrOptions = (deprecated: boolean): Fig.Option[] =>
  deprecated
    ? [
        deprecatedOption(
          "cidr-allow",
          "Reject connections that do not match the given CIDRs",
          trafficPolicyUsageHint,
          "cidr"
        ),
        deprecatedOption(
          "cidr-deny",
          "Reject connections that match the given CIDRs",
          trafficPolicyUsageHint,
          "cidr"
        ),
      ]
    : [
        valueOption(
          "cidr-allow",
          "Reject connections that do not match the given CIDRs",
          "cidr"
        ),
        valueOption(
          "cidr-deny",
          "Reject connections that match the given CIDRs",
          "cidr"
        ),
      ];

