const apiOption = (
  name: string,
  overrides: Record<string, string> = {}
): Fig.Option => {
  const description = overrides[name] ?? apiFlagDescriptions[name];
  const option: Fig.Option = { name: `--${name}` };
  if (description) {
    option.description = description;
  }
  if (!apiBooleanFlags.has(name)) {
    option.args = { name: name.split(".").pop() ?? name };
  }
  return option;
};

const isApiGroup = (node: ApiNode): node is ApiGroup =>
  Array.isArray(node[2]);

const apiCommand = (node: ApiNode): Fig.Subcommand => {
  const [name, description] = node;
  const command: Fig.Subcommand = { name };
  if (description) {
    command.description = description;
  }
  if (isApiGroup(node)) {
    command.subcommands = node[2].map(apiCommand);
    return command;
  }
  const [, , args, flags, overrides] = node;
  const argNames = args.split(" ").filter(Boolean);
  if (argNames.length > 0) {
    const argList = argNames.map((argName): Fig.Arg => ({ name: argName }));
    command.args = argList.length === 1 ? argList[0] : argList;
  }
  const flagNames = flags.split(" ").filter(Boolean);
  if (flagNames.length > 0) {
    command.options = flagNames.map((flag) => apiOption(flag, overrides));
  }
  return command;
};

